from functools import cached_property
import statistics

class Notas:
    def __init__(self, valores):
        self._valores = tuple(valores)

    @cached_property
    def desvio(self):
        print("calculando...")
        return statistics.stdev(self._valores)

n = Notas([7, 8, 6, 9])
print(n.desvio)  # imprime 'calculando...' e o valor
print(n.desvio)  # só o valor, vindo do cache
del n.desvio     # limpa o cache
print(n.desvio)  # calcula de novo
